<?php
use App\Enums\MovementActionType; use App\Enums\MovementStatus; use App\Models\{Company,Customer,Movement,Site,User,Vehicle}; use App\Services\MovementWorkflow; use Illuminate\Support\Facades\{Auth,DB,Gate}; use Illuminate\Validation\Rule; use Livewire\Attributes\Title; use Livewire\Component;
new #[Title('Movement')] class extends Component {
 public ?Movement $movement=null; public ?int $company_id=null; public string $reference=''; public string $movement_type='delivery'; public string $status='draft'; public string $transitionReason=''; public ?string $advice_note=null,$job_number=null,$contact_name=null,$contact_number=null,$notes=null; public ?int $customer_id=null; public array $actions=[],$items=[];
 public function mount(?Movement $movement=null):void { $this->movement=$movement; if($movement){abort_unless(Auth::user()->canAccessCompany((int)$movement->company_id),403);$movement->load(['actions','items.accessories']);foreach(['company_id','reference','movement_type','advice_note','job_number','contact_name','contact_number','notes','customer_id'] as $f)$this->$f=$movement->$f;$this->status=$movement->status->value;$this->actions=$movement->actions->map(fn($a)=>['id'=>$a->id,'action_type'=>$a->action_type->value,'site_id'=>$a->site_id,'driver_id'=>$a->driver_id,'vehicle_id'=>$a->vehicle_id,'schedule_start'=>$a->schedule_start?->format('Y-m-d\TH:i'),'schedule_end'=>$a->schedule_end?->format('Y-m-d\TH:i'),'notes'=>$a->notes])->all();$this->items=$movement->items->map(fn($i)=>['id'=>$i->id,'movement_action_id'=>$i->movement_action_id,'stock_number'=>$i->stock_number,'serial_number'=>$i->serial_number,'description'=>$i->description,'movement_action'=>$i->movement_action,'accessories'=>$i->accessories->pluck('description')->join(', ')])->all();}else{$u=Auth::user();$this->company_id=$u->company_id??($u->hasRole('Super-Admin')?Company::value('id'):$u->companies()->value('companies.id'));$this->reference='MOV-'.now()->format('Ymd-His');$this->addAction();$this->addItem();}}
 public function addAction():void{$this->actions[]=['id'=>null,'action_type'=>$this->movement_type==='collection'?'collection':'delivery','site_id'=>null,'driver_id'=>null,'vehicle_id'=>null,'schedule_start'=>null,'schedule_end'=>null,'notes'=>null];} public function removeAction(int $i):void{if(count($this->actions)>1){unset($this->actions[$i]);$this->actions=array_values($this->actions);}} public function addItem():void{$this->items[]=['id'=>null,'movement_action_id'=>null,'stock_number'=>null,'serial_number'=>null,'description'=>'','movement_action'=>'delivery','accessories'=>null];} public function removeItem(int $i):void{unset($this->items[$i]);$this->items=array_values($this->items);}
 public function save():mixed {Gate::authorize($this->movement?'user.movement.update':'user.movement.create');abort_unless(Auth::user()->canAccessCompany((int)$this->company_id),403);$d=$this->validate(['company_id'=>['required','exists:companies,id'],'reference'=>['required','max:255',Rule::unique('movements')->ignore($this->movement?->id)],'movement_type'=>['required',Rule::in(['delivery','collection','exchange','trade_in'])],'customer_id'=>['required','exists:customers,id'],'advice_note'=>['nullable','max:255'],'job_number'=>['nullable','max:255'],'contact_name'=>['nullable','max:255'],'contact_number'=>['nullable','max:255'],'notes'=>['nullable','string'],'actions'=>['required','array','min:1'],'actions.*.id'=>['nullable'],'actions.*.action_type'=>['required',Rule::enum(MovementActionType::class)],'actions.*.site_id'=>['required','exists:sites,id'],'actions.*.driver_id'=>['nullable','exists:users,id'],'actions.*.vehicle_id'=>['nullable','exists:vehicles,id'],'actions.*.schedule_start'=>['nullable','date'],'actions.*.schedule_end'=>['nullable','date'],'actions.*.notes'=>['nullable','string'],'items'=>['required','array','min:1'],'items.*.id'=>['nullable'],'items.*.movement_action_id'=>['nullable'],'items.*.stock_number'=>['nullable','max:255'],'items.*.serial_number'=>['nullable','max:255'],'items.*.description'=>['required','max:255'],'items.*.movement_action'=>['required','max:50'],'items.*.accessories'=>['nullable','max:2000']]);if($this->movement&&$this->movement->status->locksRouting()){foreach(MovementWorkflow::routingFields() as $f)if((string)$this->movement->$f!==(string)($d[$f]??null)){ $this->addError($f,'Return this movement to awaiting schedule before changing routing.');return null;}if($this->itemsChanged()){$this->addError('items','Return this movement to awaiting schedule before changing machines.');return null;}}
 DB::transaction(function()use($d){$first=$d['actions'][0];$last=$d['actions'][array_key_last($d['actions'])];$md=collect($d)->except(['actions','items'])->merge(['status'=>$this->movement?->status??MovementStatus::Draft,'planned_date'=>filled($first['schedule_start'])?substr($first['schedule_start'],0,10):null,'schedule_start'=>$first['schedule_start'],'schedule_end'=>$last['schedule_end'],'collection_site_id'=>$first['site_id'],'delivery_site_id'=>$last['site_id'],'driver_id'=>$first['driver_id'],'vehicle_id'=>$first['vehicle_id'],'updated_by'=>Auth::id()])->all();if($this->movement)$this->movement->update($md);else{$md['created_by']=Auth::id();$this->movement=Movement::create($md);} $actionIds=[];foreach($d['actions'] as $n=>$r){$a=$this->movement->actions()->updateOrCreate(['id'=>$r['id']??null],collect($r)->except('id')->merge(['sequence'=>$n+1])->all());$actionIds[]=$a->id;}$this->movement->actions()->whereNotIn('id',$actionIds)->delete();$itemIds=[];foreach($d['items'] as $n=>$r){$aId=$r['movement_action_id']?:($actionIds[min($n,count($actionIds)-1)]??null);$item=$this->movement->items()->updateOrCreate(['id'=>$r['id']??null],collect($r)->except(['id','accessories'])->merge(['movement_action_id'=>$aId])->all());$itemIds[]=$item->id;$item->accessories()->delete();if(filled($r['accessories']))$item->accessories()->create(['type'=>'standard','description'=>$r['accessories'],'completed'=>false]);}$this->movement->items()->whereNotIn('id',$itemIds)->delete();});Flux::toast(text:'Movement saved',variant:'success');return $this->redirectRoute('operations.movements.index',navigate:true);}
 private function itemsChanged():bool{$old=$this->movement->items->map(fn($i)=>[$i->id,$i->stock_number,$i->serial_number,$i->description,$i->movement_action])->values()->all();$new=collect($this->items)->map(fn($i)=>[$i['id'],$i['stock_number'],$i['serial_number'],$i['description'],$i['movement_action']])->values()->all();return $old!==$new;}
 public function changeStatus(string $to,MovementWorkflow $workflow):void{abort_unless($this->movement,404);$target=MovementStatus::from($to);if(in_array($target,[MovementStatus::Scheduled,MovementStatus::AwaitingSchedule,MovementStatus::OnHold,MovementStatus::Cancelled],true))Gate::authorize('user.movement.schedule');elseif($target===MovementStatus::Assigned)Gate::authorize('user.movement.assign');else Gate::authorize('user.movement.complete');$this->movement=$workflow->transition($this->movement,$target,Auth::user(),$this->transitionReason?:null);$this->status=$this->movement->status->value;$this->transitionReason='';Flux::toast(text:'Status updated',variant:'success');}
 public function with():array{$u=Auth::user();$ids=$u->hasRole('Super-Admin')?Company::pluck('id'):$u->companies()->pluck('companies.id')->push($u->company_id)->filter()->unique();return['companies'=>Company::whereIn('id',$ids)->where('is_active',true)->orderBy('name')->get(),'customers'=>Customer::orderBy('name')->get(),'sites'=>Site::orderBy('name')->get(),'drivers'=>User::whereHas('roles',fn($q)=>$q->where('name','Driver'))->where('is_active',true)->orderBy('name')->get(),'vehicles'=>Vehicle::where('is_active',true)->orderBy('name')->get()];}
}; ?>
